templateclass Liste {
  struct Maillon { T val; Maillon* suivant; };
  Maillon* premier;
public:
  Liste() : premier(nullptr) {}
  ~Liste() { while(premier) Supprimer(); }        // libère tout → pas de fuite
  void Ajouter(const T& v) {                        // insertion en tête
    Maillon* m = new Maillon{v, premier};
    premier = m;
  }
  void Supprimer() {                                // suppression en tête
    if(!premier) return;
    Maillon* tmp = premier; premier = premier->suivant; delete tmp;
  }
  void Afficher() const {
    for(Maillon* p = premier; p; p = p->suivant) cout << p->val << " ";
    cout << "\n";
  }
};

Le destructeur parcourt et delete chaque maillon → aucune fuite mémoire. On devrait aussi interdire ou définir proprement la copie (règle des trois) pour éviter les doubles libérations.

