public class TriangleArea {
  public static void main(String[] args) {
    if (args.length != 3) {
      System.err.println("Utilisation du programme : TriangleArea a b c");
      return;
    }
    double a, b, c;
    try {
      a = Double.parseDouble(args[0]);
      b = Double.parseDouble(args[1]);
      c = Double.parseDouble(args[2]);
    } catch (NumberFormatException e) {
      System.err.println("Les trois arguments doivent être des double");
      return;
    }
    // triangle valide : inégalités triangulaires
    if (a<=0 || b<=0 || c<=0 || a+b<=c || a+c<=b || b+c<=a) {
      System.err.println("Les longueurs ne forment pas un triangle valide");
      return;
    }
    double s = (a + b + c) / 2;
    double S = Math.sqrt(s*(s-a)*(s-b)*(s-c));
    System.out.println("Surface : " + S);
  }
}
Exemples : « java TriangleArea 3 4 » → message d'usage ; « java TriangleArea 3 4 cinq » → « Les trois arguments doivent être des double » ; « java TriangleArea 3 4 5 » → « Surface : 6.0 ».

